/* IraStoria OS — desktop shell (zero dependencies). Data comes from #site-data, generated by build.py. */
(function () {
  'use strict';
  var D = JSON.parse(document.getElementById('site-data').textContent);
  var U = D.ui, lang = D.lang;
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  var isMobile = function () { return window.matchMedia('(max-width: 699px)').matches; };
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  // shell: phone (iOS-like) vs desktop. Width is the primary signal; ?shell= overrides for previews.
  var shellOverride = (/[?&]shell=(phone|desktop)/.exec(location.search) || [])[1];
  var PHONE = shellOverride ? shellOverride === 'phone' : (window.matchMedia('(max-width: 699px)').matches || (window.matchMedia('(pointer: coarse)').matches && window.innerWidth < 900));
  try { localStorage.setItem('lang', lang); } catch (e) {}
  var sw = $('[data-lang-switch]');
  if (sw) sw.addEventListener('click', function () { try { localStorage.setItem('lang', sw.getAttribute('data-lang-switch')); } catch (e) {} });

  // ============================================================ boot sequence
  var boot = $('#boot'), log = $('#boot-log'), bootBtn = $('#boot-btn'), bootHint = $('#boot-hint'), desktop = $('#desktop');
  var skipBoot = false;
  try { skipBoot = sessionStorage.getItem('booted') === '1' || location.hash === '#desktop' || /[?&]app=/.test(location.search); } catch (e) {}
  var script = [
    ['$ whoami', '> ' + D.author],
    ['$ cat about.md', '> ' + D.tagline + '\n  ' + D.hero_intro],
    ['$ ' + (lang === 'zh' ? 'echo "作曲 × 遊戲音訊 × 互動音樂"' : 'echo "music × game audio × interactive"'), '> <hl>' + (lang === 'zh' ? '讓音樂跟著玩家一起動' : 'make music move with the player') + '</hl>'],
    ['$ boot irastoria-os', '> ' + U.boot_1 + '\n> ' + U.boot_2 + '\n> ' + U.boot_3 + '\n> ' + U.boot_ready]
  ];
  var done = false;
  function enterDesktop() {
    if (done) return; done = true;
    try { sessionStorage.setItem('booted', '1'); } catch (e) {}
    boot.classList.add('out');
    desktop.hidden = false;
    setTimeout(function () { boot.remove(); }, reduced ? 0 : 500);
    initDesktop();
    // two lines grow from the edges and meet in the middle; music starts the instant they connect (user gesture = this click)
    wave.connect(function () { try { player.autoplay(); } catch (e) {} caption.arm(); });
  }
  function typeLine(text, cb) {
    var i = 0, span = document.createElement('span'); span.className = 'p'; log.appendChild(span);
    var cur = document.createElement('span'); cur.className = 'cursor'; log.appendChild(cur);
    (function step() {
      if (done) return;
      if (i <= text.length) { span.textContent = text.slice(0, i++); setTimeout(step, reduced ? 0 : 28); }
      else { cur.remove(); log.appendChild(document.createTextNode('\n')); cb(); }
    })();
  }
  function printOut(html, cb) {
    var o = document.createElement('span'); o.className = 'o'; o.innerHTML = esc(html).replace(/&lt;hl&gt;/g, '<span class="hl">').replace(/&lt;\/hl&gt;/g, '</span>');
    log.appendChild(o); log.appendChild(document.createTextNode('\n\n'));
    setTimeout(cb, reduced ? 0 : 350);
  }
  function runBoot(k) {
    if (k >= script.length) { bootBtn.hidden = false; bootHint.hidden = false; return; }
    typeLine(script[k][0], function () { printOut(script[k][1], function () { runBoot(k + 1); }); });
  }

  // ============================================================ background wave + now-playing caption
  var CONNECT_MS = 1100, DECAY_PER_SEC = 0.55, FADE_SEC = 3;   // bars keep 55%/s when paused (~7 s to silence); audio fades out over FADE_SEC on pause
  function decayFactor(dtMs) { return Math.pow(DECAY_PER_SEC, dtMs / 1000); }   // frame-rate independent (real elapsed time, so a throttled tab catches up)
  function makeWave(cv, yRatio) {
    var g2 = cv ? cv.getContext('2d') : null, connectT0 = 0, mode = 'idle', raf = null, onConnected = null, levels = [], lastT = 0;
    function size() { if (cv.width !== cv.clientWidth || cv.height !== cv.clientHeight) { cv.width = cv.clientWidth; cv.height = cv.clientHeight; } }
    function ease(x) { return 1 - Math.pow(1 - x, 3); }
    function draw() {
      raf = requestAnimationFrame(draw); size();
      var now = performance.now(), dk = decayFactor(lastT ? now - lastT : 16); lastT = now;
      var W = cv.width, H = cv.height, y = H * yRatio; g2.clearRect(0, 0, W, H);
      g2.lineWidth = 2; g2.strokeStyle = 'rgba(224,176,74,.85)'; g2.shadowColor = 'rgba(224,176,74,.6)'; g2.shadowBlur = 12;
      if (mode === 'connect') {
        var p = Math.min(1, (performance.now() - connectT0) / CONNECT_MS), e = ease(p), half = W / 2 * e;
        g2.beginPath(); g2.moveTo(0, y); g2.lineTo(half, y); g2.moveTo(W, y); g2.lineTo(W - half, y); g2.stroke();
        if (p >= 1) { mode = 'live'; if (onConnected) { var cb = onConnected; onConnected = null; cb(); } }
        return;
      }
      var an = player.analyser();
      if (mode === 'live' && an) {
        // spectrum bars (same log-frequency mapping as the player). On pause the bars fall gradually instead of vanishing.
        var n = Math.max(48, Math.min(128, Math.floor(W / 12))), bw = W / n, maxH = H * 0.28, any = false;
        var data = new Uint8Array(an.frequencyBinCount); an.getByteFrequencyData(data);
        if (levels.length !== n) levels = new Array(n).fill(0);
        g2.shadowBlur = 0;
        for (var i = 0; i < n; i++) {
          var lo = Math.floor(Math.pow(data.length, i / n)), hi = Math.max(lo + 1, Math.floor(Math.pow(data.length, (i + 1) / n))), m = 0;
          for (var b = lo; b < hi && b < data.length; b++) m = Math.max(m, data[b]);
          var target = m / 255;   // follows the real signal, so the fade-out and the bars fall together
          levels[i] = target > levels[i] ? target : Math.max(target, levels[i] * dk);
          var h = levels[i] * maxH, x = i * bw + 1; if (h > 0.5) any = true;
          g2.fillStyle = 'rgba(224,176,74,.75)'; g2.fillRect(x, y - h, bw - 2, h);
          g2.fillStyle = 'rgba(224,176,74,.18)'; g2.fillRect(x, y, bw - 2, h * 0.45);
        }
        g2.strokeStyle = any ? 'rgba(224,176,74,.9)' : 'rgba(224,176,74,.28)'; g2.shadowBlur = any ? 10 : 0; g2.beginPath(); g2.moveTo(0, y); g2.lineTo(W, y); g2.stroke();
      } else {
        g2.strokeStyle = 'rgba(224,176,74,.28)'; g2.shadowBlur = 0;
        g2.beginPath(); g2.moveTo(0, y); g2.lineTo(W, y); g2.stroke();
      }
    }
    function start(m) { if (!cv) return; mode = m || 'idle'; if (!raf) draw(); }
    function connect(cb) { if (!cv) { cb(); return; } onConnected = cb; connectT0 = performance.now(); start('connect'); }
    return { start: start, connect: connect };
  }
  var wave = makeWave($('#wave'), 0.58), phoneWave = makeWave($('#ph-wave'), 0.47);  // phone: slightly above centre

  // caption: fades in over CONNECT_MS (same as the line), follows the current track
  var caption = (function () {
    var els = [$('#np-desktop'), $('#np-phone')].filter(Boolean), timer = null, last = '';
    function refresh() {
      var st = player.state(), key = st.title + '|' + (st.started ? 1 : 0) + '|' + (st.playing ? 1 : 0);
      if (key === last) return; last = key;
      els.forEach(function (el) {
        // desktop: visible as soon as a track is loaded (so the transport works even if autoplay was blocked); phone: only once started
        var title = (el.id === 'np-desktop' || st.started) ? st.title : '';
        el.querySelector('.np-title').textContent = title; el.classList.toggle('show', !!title); el.classList.toggle('playing', st.playing);
        var pp = el.querySelector('.np-pp'); if (pp) pp.textContent = st.playing ? '❚❚' : '▶';
        var stt = el.querySelector('.np-state'); if (stt) stt.textContent = st.playing ? U.ph_now : U.ph_paused;
      });
    }
    // desktop caption doubles as a mini transport: pause / previous / next without opening the player window
    els.forEach(function (el) {
      var pp = el.querySelector('.np-pp'), pv = el.querySelector('.np-prev'), nx = el.querySelector('.np-next');
      if (pp) pp.addEventListener('click', function () { player.toggle(); refresh(); });
      if (pv) pv.addEventListener('click', function () { player.prev(); refresh(); });
      if (nx) nx.addEventListener('click', function () { player.next(); refresh(); });
      var t = el.querySelector('.np-title'); if (t && el.id === 'np-desktop') t.addEventListener('click', function () { openApp('player'); });
    });
    function arm() { player.prepare(); els.forEach(function (el) { el.style.transitionDuration = CONNECT_MS + 'ms'; }); if (!timer) timer = setInterval(refresh, 400); refresh(); }
    return { arm: arm, refresh: refresh };
  })();

  // ============================================================ desktop
  var wins = {}, z = 20, dock = $('#dock'), windowsEl = $('#windows');
  var APPS = ['works', 'demos', 'player', 'articles', 'about', 'terminal'];
  var TITLES = { works: U.app_works, demos: U.app_demos, player: U.app_player, articles: U.app_articles, about: U.app_about, terminal: U.app_terminal };
  var PAGES = { works: 'works/', demos: 'demos/', articles: 'articles/', about: 'about/' };
  var GLYPH = { works: '🎼', demos: '🎛️', player: '▶️', articles: '📝', about: '👤', terminal: '⌨️' };

  function initDesktop() {
    if (initDesktop.did) return; initDesktop.did = true;
    // clock
    var clock = $('#clock');
    (function tick() { var d = new Date(); clock.textContent = ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2); setTimeout(tick, 15000); })();
    // icons
    document.querySelectorAll('.icon[data-app]').forEach(function (b) { b.addEventListener('click', function () { openApp(b.getAttribute('data-app')); }); });
    // dock
    APPS.forEach(function (a) {
      var b = document.createElement('button'); b.setAttribute('data-app', a); b.innerHTML = '<span>' + GLYPH[a] + '</span>' + esc(TITLES[a]);
      b.addEventListener('click', function () { var w = wins[a]; if (w && !w.classList.contains('minimized') && w.classList.contains('focus')) minimize(a); else openApp(a); });
      dock.appendChild(b);
    });
    makeDraggable($('#sticky'), $('#sticky'));
    // deep link ?app=works
    var m = /[?&]app=([a-z]+)/.exec(location.search);
    if (m && APPS.indexOf(m[1]) >= 0) openApp(m[1]);
    else if (!isMobile()) setTimeout(function () { openApp('works'); }, reduced ? 0 : 400);
    updateDock();
  }

  function openApp(app) {
    if (PHONE) return phone.open(app);
    var w = wins[app];
    if (!w) { w = createWindow(app); wins[app] = w; }
    w.classList.remove('minimized');
    focus(w);
    updateDock();
  }
  function minimize(app) { var w = wins[app]; if (w) { w.classList.add('minimized'); w.classList.remove('focus'); } updateDock(); }
  function closeApp(app) { var w = wins[app]; if (!w) return; if (app === 'player' && player) player.stop(true); w.remove(); delete wins[app]; updateDock(); }
  function focus(w) {
    Object.keys(wins).forEach(function (k) { wins[k].classList.remove('focus'); });
    w.classList.add('focus'); w.style.zIndex = ++z;
    updateDock();
  }
  function updateDock() {
    dock.querySelectorAll('button').forEach(function (b) {
      var a = b.getAttribute('data-app'), w = wins[a];
      b.classList.toggle('open', !!w);
      b.classList.toggle('on', !!w && !w.classList.contains('minimized') && w.classList.contains('focus'));
    });
  }

  var spawn = 0;
  function createWindow(app) {
    var w = document.createElement('section'); w.className = 'win'; w.setAttribute('data-app', app); w.setAttribute('role', 'dialog'); w.setAttribute('aria-label', TITLES[app]);
    var size = { works: [560, 520], demos: [520, 420], player: [400, 520], articles: [480, 380], about: [520, 460], terminal: [560, 380] }[app];
    var vw = window.innerWidth, vh = window.innerHeight - 30;
    var W = Math.min(size[0], vw - 24), H = Math.min(size[1], vh - 100);
    var x = Math.max(110, Math.min(vw - W - 20, 140 + (spawn % 5) * 40)), y = Math.max(8, Math.min(vh - H - 90, 30 + (spawn % 5) * 32)); spawn++;
    w.style.cssText = 'left:' + x + 'px;top:' + y + 'px;width:' + W + 'px;height:' + H + 'px;z-index:' + (++z);
    w.innerHTML = '<div class="win-bar"><span class="dots"><button class="close" title="' + esc(U.win_close) + '"></button><button class="min" title="' + esc(U.win_min) + '"></button><button class="max"></button></span>' +
      '<span class="win-title">' + GLYPH[app] + ' ' + esc(TITLES[app]) + '</span></div><div class="win-body"></div>' +
      (PAGES[app] ? '<div class="win-foot"><span></span><a href="' + PAGES[app] + '">' + esc(U.open_page) + '</a></div>' : '');
    $('.close', w).addEventListener('click', function () { closeApp(app); });
    $('.min', w).addEventListener('click', function () { minimize(app); });
    $('.max', w).addEventListener('click', function () { w.classList.toggle('maxed'); if (w.classList.contains('maxed')) { w.dataset.prev = w.style.cssText; w.style.cssText = 'left:8px;top:8px;width:' + (vw - 16) + 'px;height:' + (vh - 90) + 'px;z-index:' + (++z); } else { w.style.cssText = w.dataset.prev; } });
    w.addEventListener('pointerdown', function () { focus(w); });
    makeDraggable(w, $('.win-bar', w));
    windowsEl.appendChild(w);
    RENDER[app]($('.win-body', w), w);
    return w;
  }

  function makeDraggable(el, handle) {
    var sx, sy, ox, oy, dragging = false;
    handle.addEventListener('pointerdown', function (e) {
      if (isMobile() && el.classList.contains('win')) return;
      if (e.target.tagName === 'BUTTON') return;
      dragging = true; sx = e.clientX; sy = e.clientY; ox = el.offsetLeft; oy = el.offsetTop;
      handle.setPointerCapture(e.pointerId); e.preventDefault();
    });
    handle.addEventListener('pointermove', function (e) {
      if (!dragging) return;
      var nx = ox + e.clientX - sx, ny = oy + e.clientY - sy;
      el.style.left = Math.max(-el.offsetWidth + 80, Math.min(window.innerWidth - 80, nx)) + 'px';
      el.style.top = Math.max(0, Math.min(window.innerHeight - 60, ny)) + 'px';
      el.style.right = 'auto'; el.style.bottom = 'auto'; el.style.transform = 'none';
    });
    handle.addEventListener('pointerup', function () { dragging = false; });
    handle.addEventListener('pointercancel', function () { dragging = false; });
  }

  // ============================================================ app renderers
  function mediaHTML(w) {
    var m = w.media || {};
    if (m.youtube) return '<iframe class="media" src="https://www.youtube-nocookie.com/embed/' + esc(m.youtube) + '" loading="lazy" allow="encrypted-media; picture-in-picture" allowfullscreen title="' + esc(w.title) + '"></iframe>';
    if (m.soundcloud) return '<iframe class="media" src="https://w.soundcloud.com/player/?url=' + esc(m.soundcloud) + '&color=%23e0b04a" loading="lazy" title="' + esc(w.title) + '"></iframe>';
    if (m.local) return '<audio class="media" style="aspect-ratio:auto;height:40px;background:none" controls preload="none" src="../' + esc(m.local) + '"></audio>';
    return '';
  }
  function workItem(w) {
    var m = w.media || {}, acts = [];
    if (m.demo) acts.push('<a class="btn" href="../' + esc(m.demo) + '">' + esc(U.open_demo) + '</a>');
    if (w.type === 'music' && (m.local || m.youtube || m.soundcloud)) acts.push('<button class="btn ghost" data-play="' + esc(w.id) + '">' + esc(U.listen) + '</button>');
    (w.links || []).forEach(function (l) { acts.push('<a class="btn ghost" href="' + esc(l.url) + '" rel="noopener">' + esc(l.label) + '</a>'); });
    return '<li data-type="' + esc(w.type) + '"><span class="badge ' + esc(w.type) + '">' + esc(U['type_' + w.type]) + '</span><div style="flex:1">' +
      '<div class="t">' + esc(w.title) + ' <span class="meta">' + w.year + '</span></div><div class="d">' + esc(w.desc) + '</div>' +
      (m.demo ? '' : mediaHTML(w)) + (m.demo ? '<div class="meta" style="margin:.3rem 0">' + esc(w.platform === 'desktop' ? U.platform_desktop : U.platform_all) + '</div>' : '') +
      (acts.length ? '<div style="display:flex;gap:.4rem;flex-wrap:wrap;margin-top:.4rem">' + acts.join('') + '</div>' : '') + '</div></li>';
  }

  var RENDER = {
    works: function (body) {
      var types = ['music', 'game', 'tool', 'demo'].filter(function (t) { return D.works.some(function (w) { return w.type === t; }); });
      body.innerHTML = '<div class="filter"><button class="on" data-f="all">' + esc(U.filter_all) + '</button>' + types.map(function (t) { return '<button data-f="' + t + '">' + esc(U['type_' + t]) + '</button>'; }).join('') + '</div>' +
        '<ul class="list">' + D.works.map(workItem).join('') + '</ul>';
      body.addEventListener('click', function (e) {
        var f = e.target.closest('[data-f]'); if (f) { body.querySelectorAll('[data-f]').forEach(function (b) { b.classList.toggle('on', b === f); }); body.querySelectorAll('.list li').forEach(function (li) { li.hidden = !(f.dataset.f === 'all' || li.dataset.type === f.dataset.f); }); }
        var p = e.target.closest('[data-play]'); if (p) { openApp('player'); player.playId(p.dataset.play); }
      });
    },
    demos: function (body) {
      body.innerHTML = '<p class="d">' + esc(U.demos_intro) + '</p><ul class="list">' + D.demos.map(function (d) {
        return '<li><span class="badge demo">' + esc(U.type_demo) + '</span><div style="flex:1"><div class="t">' + esc(d.title) + ' <span class="meta">' + esc(d.year || '') + '</span></div><div class="d">' + esc(d.desc) + '</div>' +
          '<div class="meta" style="margin:.3rem 0">' + esc(d.platform === 'desktop' ? U.platform_desktop : U.platform_all) + '</div><a class="btn" href="../' + esc(d.path) + '/">' + esc(U.open_demo) + '</a></div></li>';
      }).join('') + '</ul>';
    },
    articles: function (body) {
      body.innerHTML = D.articles.length ? '<ul class="list">' + D.articles.map(function (a) { return '<li><div><div class="t"><a href="articles/' + esc(a.slug) + '/">' + esc(a.title) + '</a></div><div class="meta">' + esc(a.date) + '</div></div></li>'; }).join('') + '</ul>'
        : '<p class="d">' + esc(U.articles_empty) + '</p>';
    },
    about: function (body) {
      body.innerHTML = '<h2>' + esc(D.author) + '</h2>' + D.about.map(function (p) { return '<p>' + esc(p) + '</p>'; }).join('') +
        '<h2>' + esc(U.contact_title) + '</h2><p>' + esc(U.email_label) + ': <a href="#" data-email data-u="' + esc(D.contact.email_user) + '" data-d="' + esc(D.contact.email_domain) + '">' + esc(U.email_hint) + '</a>' +
        D.contact.links.map(function (l) { return ' · <a href="' + esc(l.url) + '" rel="me noopener">' + esc(l.label) + '</a>'; }).join('') + '</p>';
      $('[data-email]', body).addEventListener('click', function (ev) { ev.preventDefault(); var a = ev.currentTarget, addr = a.dataset.u + '@' + a.dataset.d; a.textContent = addr; a.href = 'mailto:' + addr; a.removeAttribute('data-email'); });
    },
    player: function (body) { player.mount(body); },
    terminal: function (body) { terminal.mount(body); }
  };

  // ============================================================ music player (concept)
  var player = (function () {
    var tracks = D.works.filter(function (w) { return w.type === 'music' && w.media && (w.media.local || w.media.youtube || w.media.soundcloud); });
    var placeholder = { id: '_synth', title: U.player_placeholder, desc: '', synth: true };
    var list = tracks.length ? tracks : [placeholder];
    var cur = -1, playing = false, started = false, audio = null, actx = null, analyser = null, synth = null, synthStart = 0, SYNTH_LEN = 24;
    var body, ui = {}, raf, timeTimer = null, vizLevels = [], vizLastT = 0, master = null;

    function mount(b) {
      body = b;
      body.innerHTML = '<div class="player"><div class="art"><canvas id="pl-viz"></canvas><div class="np">' + esc(U.player_now) + '<b id="pl-title">—</b><span id="pl-sub"></span></div></div>' +
        '<div class="ctl"><button id="pl-prev">⏮</button><button class="play" id="pl-play">▶</button><button id="pl-next">⏭</button><div class="seek" id="pl-seek"><i></i></div><span class="time" id="pl-time">0:00 / 0:00</span></div>' +
        '<div id="pl-ext"></div><ul class="list pl" id="pl-list">' + list.map(function (t, i) { return '<li data-i="' + i + '"><span class="meta">' + ('0' + (i + 1)).slice(-2) + '</span><div><div class="t">' + esc(t.title) + '</div><div class="d">' + esc(t.desc || '') + '</div></div></li>'; }).join('') + '</ul>' +
        (tracks.length ? '' : '<p class="note">' + esc(U.player_empty) + '</p>') + '</div>';
      ui = { title: $('#pl-title', body), sub: $('#pl-sub', body), play: $('#pl-play', body), seek: $('#pl-seek', body), bar: $('#pl-seek i', body), time: $('#pl-time', body), ext: $('#pl-ext', body), list: $('#pl-list', body), viz: $('#pl-viz', body) };
      ui.play.addEventListener('click', toggle);
      $('#pl-prev', body).addEventListener('click', prev);
      $('#pl-next', body).addEventListener('click', next);
      ui.list.addEventListener('click', function (e) { var li = e.target.closest('li[data-i]'); if (li) load(+li.dataset.i, true); });
      ui.seek.addEventListener('click', function (e) { var r = ui.seek.getBoundingClientRect(), f = (e.clientX - r.left) / r.width; if (audio && audio.duration) audio.currentTime = f * audio.duration; });
      if (cur < 0) load(0, false); else refresh();
      draw(); if (!timeTimer) timeTimer = setInterval(tickTime, 250); tickTime();
    }
    function ensureCtx() { if (!actx) { actx = new (window.AudioContext || window.webkitAudioContext)(); analyser = actx.createAnalyser(); analyser.fftSize = 512; analyser.connect(actx.destination); master = actx.createGain(); master.connect(analyser); } if (actx.state === 'suspended') actx.resume(); }
    var fadeTimer = null;
    function rampDown(g) { g.gain.cancelScheduledValues(0); g.gain.setValueAtTime(Math.max(g.gain.value, 0.0001), actx.currentTime); g.gain.exponentialRampToValueAtTime(0.0001, actx.currentTime + FADE_SEC); }
    function stopAll(immediate) {
      if (fadeTimer) { clearTimeout(fadeTimer); fadeTimer = null; }
      if (audio && !audio.paused) {
        if (immediate || !master) audio.pause();
        else { rampDown(master); var a = audio; fadeTimer = setTimeout(function () { a.pause(); fadeTimer = null; }, FADE_SEC * 1000 + 50); }   // pause after the fade so the bars follow the sound down
      }
      if (synth) {
        var sg = synth.gain, nodes = synth.nodes; synth = null;
        if (immediate) sg.gain.setValueAtTime(0.0001, actx.currentTime); else rampDown(sg);
        setTimeout(function () { nodes.forEach(function (n) { try { n.stop(); } catch (e) {} }); }, immediate ? 0 : FADE_SEC * 1000 + 50);
      }
      playing = false; refresh();
    }
    function load(i, autoplay) {
      stopAll(true); cur = i; var t = list[i];
      if (ui.ext) ui.ext.innerHTML = '';
      if (t.synth || (t.media && t.media.local)) {
        if (!t.synth) { if (!audio) { audio = new Audio(); audio.addEventListener('ended', function () { load((cur + 1) % list.length, true); }); } audio.src = '../' + t.media.local; }
        if (autoplay) play();
      } else {
        var m = t.media, src = m.youtube ? 'https://www.youtube-nocookie.com/embed/' + m.youtube + (autoplay ? '?autoplay=1' : '') : 'https://w.soundcloud.com/player/?url=' + m.soundcloud + '&color=%23e0b04a' + (autoplay ? '&auto_play=true' : '');
        if (ui.ext) ui.ext.innerHTML = '<p class="note">' + esc(U.player_external) + '</p><iframe class="media" src="' + esc(src) + '" allow="autoplay; encrypted-media" title="' + esc(t.title) + '"></iframe>';
      }
      refresh();
    }
    function play() {
      var t = list[cur]; if (!t) return;
      ensureCtx();
      if (t.synth) { startSynth(); }
      else if (t.media && t.media.local) {
        if (!audio._wired) { var s = actx.createMediaElementSource(audio); s.connect(master); audio._wired = true; }
        if (fadeTimer) { clearTimeout(fadeTimer); fadeTimer = null; }
        master.gain.cancelScheduledValues(0); master.gain.setValueAtTime(1, actx.currentTime);
        var pr = audio.play(); if (pr && pr.catch) pr.catch(function () { playing = false; refresh(); caption.refresh(); });   // autoplay blocked → show ▶ again
      } else return;
      playing = true; started = true; refresh();
    }
    function toggle() { if (playing) stopAll(); else play(); }
    function playId(id) { var i = list.findIndex(function (t) { return t.id === id; }); if (i >= 0) load(i, true); }
    // Placeholder: a gentle generative pad so the player is demonstrable before real tracks exist.
    function startSynth() {
      var g = actx.createGain(); g.gain.value = 0.0001; g.connect(analyser);
      var notes = [220, 277.2, 329.6, 415.3], nodes = [];
      notes.forEach(function (f, k) {
        var o = actx.createOscillator(), og = actx.createGain(), lfo = actx.createOscillator(), lg = actx.createGain();
        o.type = k % 2 ? 'triangle' : 'sine'; o.frequency.value = f; og.gain.value = 0.12;
        lfo.frequency.value = 0.08 + k * 0.05; lg.gain.value = 0.1; lfo.connect(lg); lg.connect(og.gain);
        o.connect(og); og.connect(g); o.start(); lfo.start(); nodes.push(o, lfo);
      });
      g.gain.exponentialRampToValueAtTime(1, actx.currentTime + 2);
      synthStart = actx.currentTime; synth = { gain: g, nodes: nodes };
    }
    function fmt(s) { s = Math.max(0, s | 0); return Math.floor(s / 60) + ':' + ('0' + (s % 60)).slice(-2); }
    function refresh() {
      if (!body) return; var t = list[cur] || {};
      ui.title.textContent = t.title || '—'; ui.sub.textContent = t.synth ? 'Web Audio · generative' : (t.year || '');
      ui.play.textContent = playing ? '❚❚' : '▶';
      ui.list.querySelectorAll('li').forEach(function (li) { li.classList.toggle('on', +li.dataset.i === cur); });
    }
    function draw() {
      if (!body || !document.contains(body)) return;
      raf = requestAnimationFrame(draw);
      var nowT = performance.now(), dk = decayFactor(vizLastT ? nowT - vizLastT : 16); vizLastT = nowT;
      var c = ui.viz, g2 = c.getContext('2d'); if (c.width !== c.clientWidth) { c.width = c.clientWidth; c.height = c.clientHeight; }
      g2.clearRect(0, 0, c.width, c.height);
      if (analyser) {
        var data = new Uint8Array(analyser.frequencyBinCount); analyser.getByteFrequencyData(data);
        var n = 64, bw = c.width / n; g2.fillStyle = 'rgba(224,176,74,.55)';
        if (vizLevels.length !== n) vizLevels = new Array(n).fill(0);
        for (var i = 0; i < n; i++) { var lo = Math.floor(Math.pow(data.length, i / n)), hi = Math.max(lo + 1, Math.floor(Math.pow(data.length, (i + 1) / n))), m = 0; for (var b = lo; b < hi && b < data.length; b++) m = Math.max(m, data[b]);
          var tg = m / 255; vizLevels[i] = tg > vizLevels[i] ? tg : Math.max(tg, vizLevels[i] * dk);
          var h = vizLevels[i] * c.height; g2.fillRect(i * bw, c.height - h, bw - 1, h); }
      }
    }
    function tickTime() {
      if (!body || !document.contains(body)) { clearInterval(timeTimer); timeTimer = null; return; }
      var pos = 0, dur = 0;
      if (list[cur] && list[cur].synth && playing) { pos = (actx.currentTime - synthStart) % SYNTH_LEN; dur = SYNTH_LEN; }
      else if (audio && list[cur] && !list[cur].synth) { pos = audio.currentTime; dur = audio.duration || 0; }
      ui.bar.style.width = dur ? (pos / dur * 100) + '%' : '0'; ui.time.textContent = fmt(pos) + ' / ' + fmt(dur);
    }
    function state() {
      var t = list[cur] || {}; var pos = 0, dur = 0;
      if (t.synth && playing && actx) { pos = (actx.currentTime - synthStart) % SYNTH_LEN; dur = SYNTH_LEN; }
      else if (audio && !t.synth) { pos = audio.currentTime; dur = audio.duration || 0; }
      return { title: t.title || '', playing: playing, started: cur >= 0 && (started || playing || pos > 0), frac: dur ? pos / dur : 0 };
    }
    function autoplay() { ensureCtx(); if (cur < 0) load(0, false); if (!playing) play(); }
    function prepare() { if (cur < 0) load(0, false); }   // load first track silently so the desktop transport has something to show
    function prev() { load((cur - 1 + list.length) % list.length, true); }
    function next() { load((cur + 1) % list.length, true); }
    return { mount: mount, playId: playId, stop: stopAll, toggle: toggle, state: state, autoplay: autoplay, prepare: prepare, prev: prev, next: next,
             analyser: function () { return analyser; }, isPlaying: function () { return playing; } };
  })();

  // ============================================================ terminal app (playful nav)
  var terminal = (function () {
    var body, out, input;
    function mount(b) {
      body = b; body.innerHTML = '<div class="term"><div class="out" id="t-out"></div><div class="in"><span>$</span><input id="t-in" autocomplete="off" spellcheck="false" aria-label="terminal"></div></div>';
      out = $('#t-out', body); input = $('#t-in', body);
      print(U.term_help + '\n');
      input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { var c = input.value.trim(); input.value = ''; print('$ ' + c); run(c); } });
      setTimeout(function () { input.focus(); }, 50);
    }
    function print(s) { out.textContent += s + '\n'; out.scrollTop = out.scrollHeight; }
    function run(c) {
      var a = c.split(/\s+/)[0];
      if (!a) return;
      if (a === 'help') print(U.term_help);
      else if (a === 'clear') out.textContent = '';
      else if (a === 'works' || a === 'ls') { print(D.works.map(function (w) { return '  ' + w.year + '  [' + w.type + ']  ' + w.title; }).join('\n')); openApp('works'); }
      else if (a === 'demos') openApp('demos');
      else if (a === 'about' || a === 'whoami') { print('> ' + D.author + ' — ' + D.tagline); openApp('about'); }
      else if (a === 'play') { openApp('player'); player.toggle(); }
      else if (a === 'lang') { location.href = '../' + (lang === 'zh' ? 'en' : 'zh') + '/#desktop'; }
      else print(U.term_unknown + a);
    }
    return { mount: mount };
  })();

  // ============================================================ phone shell (iOS-like)
  var phone = (function () {
    var root = $('#phone'), lock = $('#ph-lock'), home = $('#ph-home'), grid = $('#ph-grid'), dockEl = $('#ph-dock'), appsEl = $('#ph-apps'), mini = $('#ph-mini');
    var stack = [], miniTimer = null, unlocked = false;
    var HOME_APPS = ['works', 'demos', 'player', 'articles', 'about', 'terminal', 'lang'];
    var DOCK_APPS = ['works', 'demos', 'player', 'about'];
    function label(a) { return a === 'lang' ? U.lang_switch : TITLES[a]; }
    function glyph(a) { return a === 'lang' ? (lang === 'zh' ? 'EN' : '中') : GLYPH[a]; }
    function appBtn(a) {
      var b = document.createElement('button'); b.className = 'ph-app'; b.setAttribute('data-app', a);
      b.innerHTML = '<span class="ic ' + a + '">' + glyph(a) + '</span><span>' + esc(label(a)) + '</span>';
      b.addEventListener('click', function () {
        if (a === 'lang') { try { localStorage.setItem('lang', lang === 'zh' ? 'en' : 'zh'); } catch (e) {} location.href = '../' + (lang === 'zh' ? 'en' : 'zh') + '/#desktop'; }
        else open(a);
      });
      return b;
    }
    function clock() {
      var d = new Date(), t = d.getHours() + ':' + ('0' + d.getMinutes()).slice(-2);
      $('#ph-time').textContent = t; $('#ph-lock-time').textContent = t;
      $('#ph-lock-date').textContent = d.toLocaleDateString(lang === 'zh' ? 'zh-TW' : 'en-US', { weekday: 'long', month: 'long', day: 'numeric' });
    }
    function init() {
      root.hidden = false; clock(); setInterval(clock, 15000);
      HOME_APPS.forEach(function (a) { grid.appendChild(appBtn(a)); });
      DOCK_APPS.forEach(function (a) { dockEl.appendChild(appBtn(a)); });
      var y0 = null;
      lock.addEventListener('pointerdown', function (e) { y0 = e.clientY; });
      lock.addEventListener('pointerup', function (e) { if (y0 === null || y0 - e.clientY > 40 || Math.abs(y0 - e.clientY) < 8) unlock(); y0 = null; });
      var skip = false; try { skip = sessionStorage.getItem('unlocked') === '1' || /[?&]app=/.test(location.search); } catch (e) {}
      if (skip) unlock(true);
      window.addEventListener('popstate', function () { if (stack.length) close(true); });
      var m = /[?&]app=([a-z]+)/.exec(location.search);
      if (m && APPS.indexOf(m[1]) >= 0) open(m[1]);
    }
    function unlock(instant) {
      if (unlocked) return; unlocked = true;
      try { sessionStorage.setItem('unlocked', '1'); } catch (e) {}
      lock.classList.add('up'); home.hidden = false;
      setTimeout(function () { lock.remove(); }, (instant || reduced) ? 0 : 400);
      if (instant) { phoneWave.start('live'); caption.arm(); }
      else phoneWave.connect(function () { try { player.autoplay(); } catch (e) {} caption.arm(); updateMini(); });
    }
    function open(app) {
      if (!unlocked) unlock(true);
      var top = stack[stack.length - 1];
      if (top && top.dataset.app === app) return;
      var pnl = document.createElement('section'); pnl.className = 'papp'; pnl.dataset.app = app; pnl.setAttribute('role', 'dialog');
      pnl.innerHTML = '<div class="papp-nav"><button class="back">‹ ' + esc(stack.length ? label(stack[stack.length - 1].dataset.app) : U.ph_home) + '</button><span class="ttl">' + esc(TITLES[app]) + '</span>' +
        (PAGES[app] ? '<a class="more" href="' + PAGES[app] + '">' + esc(U.open_page) + '</a>' : '<span class="more"></span>') + '</div><div class="papp-body"></div>';
      $('.back', pnl).addEventListener('click', function () { history.back(); });
      appsEl.appendChild(pnl); stack.push(pnl);
      history.pushState({ app: app }, '', location.pathname + location.search + '#' + app);
      RENDER[app]($('.papp-body', pnl), pnl);
      updateMini();
    }
    function close(fromHistory) {
      var pnl = stack.pop(); if (!pnl) return;
      pnl.classList.add('out'); setTimeout(function () { pnl.remove(); }, reduced ? 0 : 220);
      if (!fromHistory) history.back();
      updateMini();
    }
    function updateMini() {
      var st = player.state(), showing = st.started && !(stack.length && stack[stack.length - 1].dataset.app === 'player');
      mini.hidden = !showing;
      if (showing) {
        if (!mini.firstChild) {
          mini.innerHTML = '<div class="art">♪</div><div class="info"><b></b><span></span></div><button class="pp"></button><button class="up">⌃</button><div class="prog"><i></i></div>';
          $('.pp', mini).addEventListener('click', function () { player.toggle(); updateMini(); });
          $('.up', mini).addEventListener('click', function () { open('player'); });
        }
        $('.info b', mini).textContent = st.title; $('.info span', mini).textContent = st.playing ? U.ph_now : U.ph_paused;
        $('.pp', mini).textContent = st.playing ? '❚❚' : '▶'; $('.prog i', mini).style.width = (st.frac * 100) + '%';
        if (!miniTimer) miniTimer = setInterval(updateMini, 500);
      } else if (miniTimer) { clearInterval(miniTimer); miniTimer = null; }
    }
    return { init: init, open: open };
  })();

  // ============================================================ kick-off (after all apps are defined)
  if (PHONE) { boot.remove(); desktop.remove(); phone.init(); }
  else if (skipBoot) { boot.remove(); desktop.hidden = false; initDesktop(); wave.start('live'); caption.arm(); }
  else {
    runBoot(0);
    bootBtn.addEventListener('click', enterDesktop);
    boot.addEventListener('click', function (e) { if (e.target !== bootBtn) enterDesktop(); });
    document.addEventListener('keydown', function (e) { if (!done && (e.key === 'Enter' || e.key === ' ')) enterDesktop(); });
  }
})();
